def binary_search(items, target):
    """Return the index of target in the sorted list items, or -1."""
    low, high = 0, len(items) - 1
    while low <= high:
        middle = (low + high) // 2
        if items[middle] == target:
            return middle
        if items[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1


assert binary_search([1, 3, 5, 7, 9], 7) == 3
assert binary_search([1, 3, 5, 7, 9], 4) == -1

/// A fixed-capacity ring buffer that overwrites its oldest entry.
pub struct Ring<T> {
    slots: Vec<Option<T>>,
    next: usize,
}

impl<T: Clone> Ring<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        Self { slots: vec![None; capacity], next: 0 }
    }

    pub fn push(&mut self, value: T) {
        let index = self.next % self.slots.len();
        self.slots[index] = Some(value);
        self.next += 1;
    }
}

__global__ void rmsnorm(const float* x, const float* weight, float* y, int cols, float eps) {
    extern __shared__ float partial[];
    const float* row = x + blockIdx.x * cols;
    float sum = 0.0f;
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        sum += row[i] * row[i];
    }
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    float scale = rsqrtf(partial[0] / cols + eps);
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        y[blockIdx.x * cols + i] = row[i] * scale * weight[i];
    }
}
